package com.servicerca.security; import com.servicerca.model.User;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
@Service public class JwtService{private final byte[]secret;private static final long EXPIRATION_SECONDS=1200;public JwtService(@Value("${app.jwt-secret}")String secret){this.secret=secret.getBytes(StandardCharsets.UTF_8);}public String generateToken(User u){return Jwts.builder().subject(u.getId().toString()).claim("email",u.getEmail()).issuedAt(new Date()).expiration(Date.from(Instant.now().plusSeconds(EXPIRATION_SECONDS))).signWith(Keys.hmacShaKeyFor(secret)).compact();}public UUID parseUserId(String token){return UUID.fromString(Jwts.parser().verifyWith(Keys.hmacShaKeyFor(secret)).build().parseSignedClaims(token).getPayload().getSubject());}public long getExpirationSeconds(){return EXPIRATION_SECONDS;}}
